def migrate_legacy_interactions(apps, schema_editor):
    """把旧的单轮 AI 问答迁移成会话 + 消息，避免历史丢失。"""
    AIInteraction = apps.get_model("learning_logs", "AIInteraction")
    ChatSession = apps.get_model("learning_logs", "ChatSession")
    ChatMessage = apps.get_model("learning_logs", "ChatMessage")

    sessions = {}
    for item in AIInteraction.objects.all().order_by("created_at", "id"):
        key = (item.user_id, item.topic_id)
        session = sessions.get(key)
        if session is None:
            session = ChatSession.objects.create(
                user_id=item.user_id,
                topic_id=item.topic_id,
                title=(item.question or "历史对话")[:40],
                model_name=item.model_used or "",
            )
            sessions[key] = session
        ChatMessage.objects.create(
            session=session,
            role="user",
            content=item.question,
            model_name=item.model_used or "",
        )
        ChatMessage.objects.create(
            session=session,
            role="assistant",
            content=item.response,
            model_name=item.model_used or "",
        )


